fn shifted_letter(letters: List[String], index: Int, k: Int, fallback: String) -> String {
  let base = index / 26 * 26
  let offset = ((index % 26 + k % 26) % 26 + 26) % 26
  return letters
    |> drop(base + offset)
    |> first()
    |> unwrap_or(fallback)
}

fn shift_char(c: String, k: Int) -> String {
  let letters = split("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", "")
  let hits = filter(enumerate(letters), |p| p.1 == c)
  return match first(hits) {
    Some(p) => shifted_letter(letters, p.0, k, c),
    None => c,
  }
}

fn caesar_shift(s: String, k: Int) -> String {
  return s
    |> split("")
    |> map(|c| shift_char(c, k))
    |> join("")
}

test "wraps within each case" {
  assert(caesar_shift("Zz", 1) == "Aa")
  assert(caesar_shift("Aa", -27) == "Zz")
}

test "leaves other characters unchanged" {
  assert(caesar_shift("Az 9! éΩ", 1) == "Ba 9! éΩ")
}

