fn word_pieces(words: List[String], width: Int) -> List[String] {
  if width <= 0 {
    return words
  }
  var pieces = []
  for word in words {
    if str_len(word) <= width {
      pieces = append(pieces, word)
    } else {
      var piece = ""
      for ch in split(word, "") {
        piece = piece + ch
        if str_len(piece) == width {
          pieces = append(pieces, piece)
          piece = ""
        }
      }
      if piece != "" {
        pieces = append(pieces, piece)
      }
    }
  }
  return pieces
}

fn wrap_text(s: String, width: Int) -> List[String] {
  let words = filter(split(s, " "), |w| w != "")
  let pieces = word_pieces(words, width)
  var lines = []
  var cur = ""
  for w in pieces {
    if cur == "" {
      cur = w
    } else if str_len(cur) + 1 + str_len(w) <= width {
      cur = cur + " " + w
    } else {
      lines = append(lines, cur)
      cur = w
    }
  }
  if cur != "" {
    lines = append(lines, cur)
  }
  return lines
}

test "the last piece can share a line with the next word" {
  assert(wrap_text("  abcdefghi  x ", 4) == ["abcd", "efgh", "i x"])
}

test "nonpositive widths preserve the original behavior" {
  assert(wrap_text("  abc  de ", 0) == ["abc", "de"])
  assert(wrap_text("abc de", -1) == ["abc", "de"])
}

