type Student {
  name: String,
  scores: List[Int],
}

fn median(xs: List[Int]) -> Float {
  let s = sort_by(xs, |x| x)
  let n = len(s)
  let a = s
    |> drop((n - 1) / 2)
    |> first()
    |> unwrap_or(0)
  let b = s
    |> drop(n / 2)
    |> first()
    |> unwrap_or(0)
  return to_float(a + b) / 2.0
}

fn combined_scores(records: List[Student]) -> List[Int] {
  var scores = match first(records) {
    Some(record) => record.scores,
    None => [],
  }
  for record in drop(records, 1) {
    for score in record.scores {
      scores = append(scores, score)
    }
  }
  return scores
}

fn student_medians(students: List[Student]) -> List[(String, Float)] {
  return students
    |> group_by(|s| s.name)
    |> map(|name, records| (name, combined_scores(records)))
    |> filter(|r| len(r.1) > 0)
    |> map(|r| (r.0, median(r.1)))
    |> sort_by(|r| r.0)
    |> sort_desc_by(|r| r.1)
}

