def top_product_per_region(sales: list[Sale]) -> list[tuple[str, str, int]]:
    """Return all highest-revenue products per region, ordered by region and product."""
    revenue: dict[str, dict[str, int]] = {}
    for sale in sales:
        products = revenue.setdefault(sale["region"], {})
        products[sale["product"]] = (
            products.get(sale["product"], 0) + sale["units"] * sale["price_cents"]
        )

    result: list[tuple[str, str, int]] = []
    for region in sorted(revenue):
        products = revenue[region]
        highest = max(products.values())
        for product in sorted(name for name, total in products.items() if total == highest):
            result.append((region, product, highest))
    return result

