class Right(TypedDict):
    kind: Literal["Right"]
    n: int

class Undo(TypedDict):
    kind: Literal["Undo"]

class Redo(TypedDict):
    kind: Literal["Redo"]

EditOp = Insert | Delete | Left | Right | Undo | Redo


def text_editor(ops: list[EditOp]) -> str:
    """Apply editing operations to an initially empty line and return the final text."""
    text = ""
    cursor = 0
    undo_history: list[tuple[str, int]] = []
    redo_history: list[tuple[str, int]] = []
    for op in ops:
        if op["kind"] == "Insert":
            undo_history.append((text, cursor))
            redo_history.clear()
            text = text[:cursor] + op["text"] + text[cursor:]
            cursor += len(op["text"])
        elif op["kind"] == "Delete":
            undo_history.append((text, cursor))
            redo_history.clear()
            removed = min(op["n"], cursor)
            text = text[: cursor - removed] + text[cursor:]
            cursor -= removed
        elif op["kind"] == "Left":
            cursor = max(cursor - op["n"], 0)
        elif op["kind"] == "Right":
            cursor = min(cursor + op["n"], len(text))
        elif op["kind"] == "Undo":
            if undo_history:
                redo_history.append((text, cursor))
                text, cursor = undo_history.pop()
        elif op["kind"] == "Redo":
            if redo_history:
                undo_history.append((text, cursor))
                text, cursor = redo_history.pop()
    return text

