def wrap_text(s: str, width: int) -> list[str]:
    """Split long words, then greedily wrap the pieces into lines."""
    lines: list[str] = []
    current = ""
    for word in s.split(" "):
        if not word:
            continue
        # Preserve the original behavior for nonpositive widths.
        size = width if width > 0 else len(word)
        for start in range(0, len(word), size):
            piece = word[start : start + size]
            if not current:
                current = piece
            elif len(current) + 1 + len(piece) <= width:
                current = f"{current} {piece}"
            else:
                lines.append(current)
                current = piece
    if current:
        lines.append(current)
    return lines

