fn closer(c: String) -> String {
  return match c {
    "(" => ")",
    "[" => "]",
    "{" => "}",
    _ => "",
  }
}

fn bracket_depth(s: String) -> Result[Int, String] {
  var stack = []
  var best = 0
  var in_string = false
  for (i, c) in enumerate(split(s, "")) {
    if c == "\"" {
      in_string = !in_string
    } else if !in_string {
      let expected = closer(c)
      if expected != "" {
        stack = append(stack, expected)
        best = max(best, len(stack))
      } else if c == ")" || c == "]" || c == "}" {
        if unwrap_or(last(stack), "") != c {
          return Err("mismatch at " + to_string(i))
        }
        stack = take(stack, len(stack) - 1)
      }
    }
  }
  if in_string {
    return Err("unclosed string")
  }
  if len(stack) > 0 {
    return Err("unclosed at end")
  }
  return Ok(best)
}

