type Sale = { region: string; product: string; units: number; price_cents: number };

export function top_product_per_region(sales: Sale[]): ([string, string, number])[] {
  const byRegion = new Map<string, Map<string, number>>();
  for (const s of sales) {
    let m = byRegion.get(s.region);
    if (!m) {
      m = new Map();
      byRegion.set(s.region, m);
    }
    m.set(s.product, (m.get(s.product) ?? 0) + s.units * s.price_cents);
  }

  const compareProducts = (a: string, b: string): number => {
    let i = 0;
    while (i < a.length && i < b.length) {
      const left = a.codePointAt(i)!;
      const right = b.codePointAt(i)!;
      if (left !== right) return left - right;
      i += left > 0xffff ? 2 : 1;
    }
    return a.length - b.length;
  };

  const regions = [...byRegion.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const result: ([string, string, number])[] = [];
  for (const region of regions) {
    let bestRevenue: number | undefined;
    let bestProducts: string[] = [];
    for (const [product, revenue] of byRegion.get(region)!) {
      if (bestRevenue === undefined || revenue > bestRevenue) {
        bestRevenue = revenue;
        bestProducts = [product];
      } else if (revenue === bestRevenue) {
        bestProducts.push(product);
      }
    }
    if (bestRevenue !== undefined) {
      for (const product of bestProducts.sort(compareProducts)) {
        result.push([region, product, bestRevenue]);
      }
    }
  }
  return result;
}

