fn shift_char(c: String, k: Int) -> String {
  let letters = split("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", "")
  let hits = filter(enumerate(letters), |p| p.1 == c)
  let index = match first(hits) {
    Some(p) => p.0,
    None => -1,
  }
  if index < 0 {
    return c
  }
  let base = index / 26 * 26
  let shifted = base + (index % 26 + k % 26 + 26) % 26
  return letters
    |> drop(shifted)
    |> first()
    |> unwrap_or(c)
}

fn caesar_shift(s: String, k: Int) -> String {
  return s
    |> split("")
    |> map(|c| shift_char(c, k))
    |> join("")
}

test "wraps both cases and preserves other characters" {
  assert(caesar_shift("Zz 9!é", 1) == "Aa 9!é")
  assert(caesar_shift("Aa 9!é", -1) == "Zz 9!é")
}

