fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  if len(xs) == 0 {
    return None
  }
  var best = (unwrap_or(first(xs), 0), 0, 0)
  for (start, _) in enumerate(xs) {
    var s = 0
    for (offset, value) in enumerate(drop(xs, start)) {
      s = s + value
      let best_span = best.2 - best.1
      if s > best.0 || (s == best.0 && offset < best_span) {
        best = (s, start, start + offset)
      }
    }
  }
  return Some(best)
}

