fn nearer_above(start: Int, upper: Int, lower: Int) -> Bool {
  let midpoint = upper / 2 + lower / 2
  let remainder = upper % 2 + lower % 2
  if remainder > 0 {
    return start > midpoint
  }
  if remainder == -2 {
    return start >= midpoint - 1
  }
  return start >= midpoint
}

fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {
  let floors = map(group_by(requests, |f| f), |g| g.0)
  let above = sort_by(filter(floors, |f| f > start), |f| f)
  let below = sort_desc_by(filter(floors, |f| f < start), |f| f)
  var goes_up = direction == "up"
  if direction == "nearest" {
    goes_up = match (first(above), first(below)) {
      (Some(upper), Some(lower)) => nearer_above(start, upper, lower),
      (None, Some(_)) => false,
      _ => true,
    }
  }
  var out = filter(floors, |f| f == start)
  var rest = below
  if goes_up {
    for f in above {
      out = append(out, f)
    }
  } else {
    rest = above
    for f in below {
      out = append(out, f)
    }
  }
  for f in rest {
    out = append(out, f)
  }
  return out
}

