  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn pay(e: Employee) -> Int {
  if e.hours <= 40 {
    return e.hours * e.rate_cents
  }
  let overtime_hours = min(e.hours, 60) - 40
  let overtime_pay = overtime_hours * e.rate_cents * 3 / 2
  let double_time_pay = max(e.hours - 60, 0) * e.rate_cents * 2
  return 40 * e.rate_cents + overtime_pay + double_time_pay
}

