      _ => 0,
    }
    d = match c {
      TurnLeft => (d + 3) % 4,
      TurnRight => (d + 1) % 4,
      _ => d,
    }
    let move_dir = match c {
      Backward(_) => (d + 2) % 4,
      _ => d,
    }
    let dv = delta(move_dir)
    var k = 0
    while k < steps {
      let next = (x + dv.0, y + dv.1)
      if contains(obstacles, next) {
        break
      }
      x = next.0
      y = next.1
      k = k + 1
    }
  }
  let names = ["N", "E", "S", "W"]
  let facing = names
    |> drop(d)
    |> first()
    |> unwrap_or("N")
  return (x, y, facing)
}

