type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo
  | Redo

type Editor {
  text: String,
  cur: Int,
  history: List[(String, Int)],
  redo_history: List[(String, Int)],
}

fn step(e: Editor, op: EditOp) -> Editor {
  return match op {
    Insert(t) => insert(e, t),
    Delete(n) => delete(e, min(n, e.cur)),
    Left(n) => move_cursor(e, max(0, e.cur - n)),
    Right(n) => move_cursor(e, min(len(split(e.text, "")), e.cur + n)),
    Undo => undo(e),
    Redo => redo(e),
  }
}

fn move_cursor(e: Editor, cur: Int) -> Editor {
  var moved = e
  moved.cur = cur
  return moved
}

fn insert(e: Editor, t: String) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur), "") + t + join(drop(cs, e.cur), "")
  let saved = append(e.history, (e.text, e.cur))
  return Editor { text: text, cur: e.cur + str_len(t), history: saved, redo_history: [] }
}

fn delete(e: Editor, k: Int) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur - k), "") + join(drop(cs, e.cur), "")
  let saved = append(e.history, (e.text, e.cur))
  return Editor { text: text, cur: e.cur - k, history: saved, redo_history: [] }
}

fn undo(e: Editor) -> Editor {
  let n = len(e.history)
  let saved = append(e.redo_history, (e.text, e.cur))
  return match last(e.history) {
    Some(p) => Editor {
      text: p.0,
      cur: p.1,
      history: take(e.history, n - 1),
      redo_history: saved,
    },
    None => e,
  }
}

fn redo(e: Editor) -> Editor {
  let n = len(e.redo_history)
  let saved = append(e.history, (e.text, e.cur))
  return match last(e.redo_history) {
    Some(p) => Editor {
      text: p.0,
      cur: p.1,
      history: saved,
      redo_history: take(e.redo_history, n - 1),
    },
    None => e,
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  let start = Editor { text: "", cur: 0, history: [], redo_history: [] }
  return fold(ops, start, |e, op| step(e, op)).text
}

