  | Ident(name: String)
  | Sym(text: String)
  | Str(text: String)

fn at(cs: List[String], i: Int) -> String {
  return cs
    |> drop(i)
    |> first()
    |> unwrap_or("")
}

fn is_digit(c: String) -> Bool {
  return str_len(c) == 1 && c >= "0" && c <= "9"
}

fn is_start(c: String) -> Bool {
  return str_len(c) == 1 && (c >= "a" && c <= "z" || c == "_")
}

fn tokenize(s: String) -> Result[List[Token], String] {
  let cs = split(s, "")
  let n = len(cs)
  var i = 0
  var out = []
  while i < n {
    let c = at(cs, i)
    let two = c + at(cs, i + 1)
    if c == " " {
      i = i + 1
    } else if c == "\"" {
      let start = i
      var text = ""
      i = i + 1
      while i < n && at(cs, i) != "\"" {
        text = text + at(cs, i)
        i = i + 1
      }
      if i == n {
        return Err("unterminated string at " + to_string(start))
      }
      out = append(out, Str(text))
      i = i + 1
    } else if is_digit(c) {
      var v = 0
      while is_digit(at(cs, i)) {
        v = v * 10 + (cs |> at(i) |> parse_int() |> unwrap_or(0))
        i = i + 1
      }
      out = append(out, Num(v))
    } else if is_start(c) {
      var name = ""
      while is_start(at(cs, i)) || is_digit(at(cs, i)) {
        name = name + at(cs, i)
        i = i + 1
      }
      out = append(out, Ident(name))
    } else if contains(["==", "<=", ">=", "!="], two) {
      out = append(out, Sym(two))
      i = i + 2
    } else if contains(["+", "-", "*", "/", "=", "<", ">", "(", ")", ","], c) {
      out = append(out, Sym(c))
      i = i + 1
    } else {
      return Err("unexpected character: " + c + " at " + to_string(i))
    }
  }
  return Ok(out)
}

