fn split_long_words(words: List[String], width: Int) -> List[String] {
  if width <= 0 {
    return words
  }
  var pieces = []
  for w in words {
    if str_len(w) <= width {
      pieces = append(pieces, w)
    } else {
      var piece = ""
      for ch in split(w, "") {
        piece = piece + ch
        if str_len(piece) == width {
          pieces = append(pieces, piece)
          piece = ""
        }
      }
      if piece != "" {
        pieces = append(pieces, piece)
      }
    }
  }
  return pieces
}

fn wrap_text(s: String, width: Int) -> List[String] {
  let words = filter(split(s, " "), |w| w != "")
  let pieces = split_long_words(words, width)
  var lines = []
  var cur = ""
  for w in pieces {
    if cur == "" {
      cur = w
    } else if str_len(cur) + 1 + str_len(w) <= width {
      cur = cur + " " + w
    } else {
      lines = append(lines, cur)
      cur = w
    }
  }
  if cur != "" {
    lines = append(lines, cur)
  }
  return lines
}

test "short final piece can share a line" {
  assert(wrap_text("  abcdefghi  x ", 4) == ["abcd", "efgh", "i x"])
}

test "exact chunks do not add an empty piece" {
  assert(wrap_text("abcdefgh", 4) == ["abcd", "efgh"])
}

test "nonpositive widths keep words whole" {
  assert(wrap_text("abc  de", 0) == ["abc", "de"])
  assert(wrap_text("abc  de", -1) == ["abc", "de"])
}

