type Sale {
  region: String,
  product: String,
  units: Int,
  price_cents: Int,
}

fn ranked_products(sales: List[Sale]) -> List[(String, Int)] {
  return sales
    |> group_by(|s| s.product)
    |> map(|g| (g.0, sum(map(g.1, |s| s.units * s.price_cents))))
    |> sort_by(|p| p.0)
    |> sort_desc_by(|p| p.1)
}

fn best(region: String, sales: List[Sale]) -> (String, String, Int) {
  let totals = ranked_products(sales)
  let top = unwrap_or(first(totals), ("", 0))
  return (region, top.0, top.1)
}

fn empty_rows() -> List[(String, String, Int)] {
  return []
}

fn top_product_per_region(sales: List[Sale]) -> List[(String, String, Int)] {
  let regions = sort_by(group_by(sales, |s| s.region), |g| g.0)
  var rows = empty_rows()
  for (region, region_sales) in regions {
    let totals = ranked_products(region_sales)
    let top = unwrap_or(first(totals), ("", 0))
    for (product, revenue) in totals {
      if revenue != top.1 {
        break
      }
      rows = append(rows, (region, product, revenue))
    }
  }
  return rows
}

