def spiral_order(m: list[list[int]], clockwise: bool) -> list[int]:
    """Return a rectangular matrix's elements in spiral order from the top-left."""
    if not m or not m[0]:
        return []

    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1
    out: list[int] = []

