export function caesar_shift(s: string, k: number): string {
  let out = "";
  for (const c of s) {
    let base: number;
    if (c >= "a" && c <= "z") {
      base = 97;
    } else if (c >= "A" && c <= "Z") {
      base = 65;
    } else {
      out += c;
      continue;
    }
    const i = (((c.charCodeAt(0) - base + k) % 26) + 26) % 26;
    out += String.fromCharCode(base + i);
  }
  return out;
}

