function stripPrefix(v: string): string {
  return v.startsWith("v") || v.startsWith("V") ? v.slice(1) : v;
}

function valid(v: string): boolean {
  const parts = v.split(".");
  return parts.length <= 4 && parts.every((p) => /^[0-9]+$/.test(p));
}

export function compare_versions(a: string, b: string): Result<number> {
  const versionA = stripPrefix(a);
  if (!valid(versionA)) return { ok: false, error: "bad version: " + a };
  const versionB = stripPrefix(b);
  if (!valid(versionB)) return { ok: false, error: "bad version: " + b };

  const x = versionA.split(".").map(Number);
  const y = versionB.split(".").map(Number);
  for (let i = 0; i < 4; i++) {
    const p = x[i] ?? 0;
    const q = y[i] ?? 0;
    if (p !== q) return { ok: true, value: p < q ? -1 : 1 };
  }
  return { ok: true, value: 0 };
}

