# ruff: noqa: F401


def wrap_text(s: str, width: int) -> list[str]:
    """Split long words into pieces, then greedily wrap them."""
    lines: list[str] = []
    current = ""
    for word in s.split(" "):
        if not word:
            continue
        # Preserve the original behavior for nonpositive widths.
        step = width if width > 0 else len(word)
        for start in range(0, len(word), step):
            piece = word[start : start + step]
            if not current:
                current = piece
            elif len(current) + 1 + len(piece) <= width:
                current = f"{current} {piece}"
            else:
                lines.append(current)
                current = piece
    if current:
        lines.append(current)
    return lines

