    else if (c.kind === "TurnRight") d = (d + 1) % 4;
    else {
      const moveDir = c.kind === "Backward" ? (d + 2) % 4 : d;
      for (let k = 0; k < c.steps; k++) {
        const nx = x + dx[moveDir];
        const ny = y + dy[moveDir];
        if (blocked.has(nx + "," + ny)) break;
        x = nx;
        y = ny;
      }
    }
  }

