export function spiral_order(m: number[][], clockwise: boolean): number[] {
  const out: number[] = [];
  if (m.length === 0 || m[0].length === 0) return out;

  let top = 0;
  let bottom = m.length - 1;
  let left = 0;
  let right = m[0].length - 1;

  while (top <= bottom && left <= right) {
    if (clockwise) {
      for (let c = left; c <= right; c++) out.push(m[top][c]);
      for (let r = top + 1; r <= bottom; r++) out.push(m[r][right]);
      if (top < bottom) {
        for (let c = right - 1; c >= left; c--) out.push(m[bottom][c]);
      }
      if (left < right) {
        for (let r = bottom - 1; r > top; r--) out.push(m[r][left]);
      }
