type Student = { name: string; scores: number[] };

export function student_medians(students: Student[]): ([string, number])[] {
  const scoresByName = new Map<string, number[]>();
  for (const { name, scores } of students) {
    if (scores.length === 0) continue;
    let combined = scoresByName.get(name);
    if (combined === undefined) {
      combined = [];
      scoresByName.set(name, combined);
    }
    for (const score of scores) combined.push(score);
  }

  const rows: [string, number][] = [];
  for (const [name, scores] of scoresByName) {
    scores.sort((a, b) => a - b);
    const n = scores.length;
    const mid = Math.floor(n / 2);
    const median = n % 2 === 1 ? scores[mid] : (scores[mid - 1] + scores[mid]) / 2;
    rows.push([name, median]);
  }

  rows.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return rows;
}

