export function wrap_text(s: string, width: number): string[] {
  const words = s.split(" ").filter((w) => w !== "");
  const lines: string[] = [];
  const canSplit = Number.isInteger(width) && width > 0;
  let cur = "";

  function append(piece: string): void {
    if (cur === "") cur = piece;
    else if (cur.length + 1 + piece.length <= width) cur += " " + piece;
    else {
      lines.push(cur);
      cur = piece;
    }
  }

  for (const word of words) {
    if (canSplit && word.length > width) {
      for (let start = 0; start < word.length; start += width) {
        append(word.slice(start, start + width));
      }
    } else {
      append(word);
    }
  }

  if (cur !== "") lines.push(cur);
  return lines;
}

