type Sale = { region: string; product: string; units: number; price_cents: number };

export function top_product_per_region(sales: Sale[]): ([string, string, number])[] {
  const byRegion = new Map<string, Map<string, number>>();
  for (const s of sales) {
    let m = byRegion.get(s.region);
    if (!m) {
      m = new Map();
      byRegion.set(s.region, m);
    }
    m.set(s.product, (m.get(s.product) ?? 0) + s.units * s.price_cents);
  }

  const regions = [...byRegion.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const result: [string, string, number][] = [];
  for (const region of regions) {
    let highest: number | undefined;
    const tied: [string, string, number][] = [];
    for (const [product, revenue] of byRegion.get(region)!) {
      if (highest === undefined || revenue > highest) {
        highest = revenue;
        tied.length = 0;
        tied.push([region, product, revenue]);
      } else if (revenue === highest) {
        tied.push([region, product, revenue]);
      }
    }

    tied.sort(([, a], [, b]) => {
      let offset = 0;
      for (const char of a) {
        const other = b.codePointAt(offset);
        if (other === undefined) return 1;
        const diff = char.codePointAt(0)! - other;
        if (diff !== 0) return diff;
        offset += char.length;
      }
      return offset === b.length ? 0 : -1;
    });

    for (const row of tied) result.push(row);
  }
  return result;
}

