fn shift_char(c: String, k: Int) -> String {
  let letters = split("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", "")
  for (i, letter) in enumerate(letters) {
    if letter == c {
      let base = i - i % 26
      let offset = (i % 26 + k % 26 + 26) % 26
      return letters
        |> drop(base + offset)
        |> first()
        |> unwrap_or(c)
    }
  }
  return c
}

