fn strip_version_prefix(v: String) -> String {
  let cs = split(v, "")
  let head = unwrap_or(first(cs), "")
  if head == "v" || head == "V" {
    return join(drop(cs, 1), "")
  }
  return v
}

fn all_digits(cs: List[String]) -> Bool {
  return len(filter(cs, |c| c >= "0" && c <= "9")) == len(cs)
}

fn valid_version(v: String) -> Bool {
  if v == "" {
    return false
  }
  let parts = split(v, ".")
  if len(parts) > 4 {
    return false
  }
  for p in parts {
    let cs = split(p, "")
    if len(cs) == 0 || !all_digits(cs) {
      return false
    }
  }
  return true
}

fn part_at(ns: List[Int], i: Int) -> Int {
  return ns
    |> drop(i)
    |> first()
    |> unwrap_or(0)
}

fn sign(d: Int) -> Int {
  if d < 0 {
    return -1
  }
  return 1
}

fn compare_versions(a: String, b: String) -> Result[Int, String] {
  let version_a = strip_version_prefix(a)
  if !valid_version(version_a) {
    return Err("bad version: " + a)
  }
  let version_b = strip_version_prefix(b)
  if !valid_version(version_b) {
    return Err("bad version: " + b)
  }
  let x = map(split(version_a, "."), |p| unwrap_or(parse_int(p), 0))
  let y = map(split(version_b, "."), |p| unwrap_or(parse_int(p), 0))
  let diffs = range(0, 4)
    |> map(|i| part_at(x, i) - part_at(y, i))
    |> filter(|d| d != 0)
  return match first(diffs) {
    Some(d) => Ok(sign(d)),
    None => Ok(0),
  }
}

test "optional version prefix" {
  assert(compare_versions("v1.2.3", "1.2.3.0") == Ok(0))
  assert(compare_versions("1.9", "V2") == Ok(-1))
}

test "invalid prefixes preserve the original input" {
  assert(compare_versions("v", "1") == Err("bad version: v"))
  assert(compare_versions("1", "vv1") == Err("bad version: vv1"))
  assert(compare_versions("1.v2", "1") == Err("bad version: 1.v2"))
}

