type Cmd =
  | Forward(steps: Int)
  | Backward(steps: Int)
  | TurnLeft
  | TurnRight

fn delta(d: Int) -> (Int, Int) {
  return match d {
    0 => (0, 1),
    1 => (1, 0),
    2 => (0, -1),
    _ => (-1, 0),
  }
}

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var x = 0
  var y = 0
  var d = 0
  for c in cmds {
    let steps = match c {
      Forward(k) => k,
      Backward(k) => k,
      _ => 0,
    }
    d = match c {
      TurnLeft => (d + 3) % 4,
      TurnRight => (d + 1) % 4,
      _ => d,
    }
    let move_dir = match c {
      Backward(_) => (d + 2) % 4,
      _ => d,
    }
    let dv = delta(move_dir)
    var k = 0
    while k < steps {
