fn up_is_nearer(start: Int, high: Int, low: Int) -> Bool {
  if low < 0 && high > 0 {
    # The sum is safe across zero; round its midpoint up to include ties.
    let total = low + high
    if total > 0 {
      return start >= total / 2 + total % 2
    }
    return start >= total / 2
  }
  return high - start <= start - low
}

fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {
  let floors = map(group_by(requests, |f| f), |g| g.0)
  let above = sort_by(filter(floors, |f| f > start), |f| f)
  let below = sort_desc_by(filter(floors, |f| f < start), |f| f)
  var go_up = direction == "up"
  if direction == "nearest" {
    go_up = match (first(above), first(below)) {
      (Some(high), Some(low)) => up_is_nearer(start, high, low),
      (None, Some(_)) => false,
      _ => true,
    }
  }
  var out = filter(floors, |f| f == start)
  var rest = below
  if go_up {
    for f in above {
      out = append(out, f)
    }
  } else {
    rest = above
    for f in below {
      out = append(out, f)
    }
  }
  for f in rest {
    out = append(out, f)
  }
  return out
}

