fn wrap_text(s: String, width: Int) -> List[String] {
  let words = filter(split(s, " "), |w| w != "")
  var pieces = []
  for w in words {
    if width > 0 && str_len(w) > width {
      var piece = ""
      for ch in split(w, "") {
        piece = piece + ch
        if str_len(piece) == width {
          pieces = append(pieces, piece)
          piece = ""
        }
      }
      if piece != "" {
        pieces = append(pieces, piece)
      }
    } else {
      pieces = append(pieces, w)
    }
  }

  var lines = []
  var cur = ""
  for w in pieces {
    if cur == "" {
      cur = w
    } else if str_len(cur) + 1 + str_len(w) <= width {
      cur = cur + " " + w
    } else {
      lines = append(lines, cur)
      cur = w
    }
  }
  if cur != "" {
    lines = append(lines, cur)
  }
  return lines
}

test "a short final piece can share a line" {
  assert(wrap_text("  abcdefg  x ", 5) == ["abcde", "fg x"])
}

test "an exact split leaves no empty piece" {
  assert(wrap_text("abcdef x", 3) == ["abc", "def", "x"])
}

test "nonpositive widths still keep words whole" {
  assert(wrap_text("abc de", 0) == ["abc", "de"])
  assert(wrap_text("abc de", -1) == ["abc", "de"])
}

