type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo
  | Redo

type Editor {
  text: String,
  cur: Int,
  history: List[(String, Int)],
  redo_history: List[(String, Int)],
}

fn step(e: Editor, op: EditOp) -> Editor {
  let cs = split(e.text, "")
  let saved = append(e.history, (e.text, e.cur))
  return match op {
    Insert(t) => insert(e, t, saved),
    Delete(n) => delete(e, min(n, e.cur), saved),
    Left(n) => move(e, max(0, e.cur - n)),
    Right(n) => move(e, min(len(cs), e.cur + n)),
    Undo => undo(e),
    Redo => redo(e),
  }
}

fn move(e: Editor, cur: Int) -> Editor {
  return Editor { text: e.text, cur: cur, history: e.history, redo_history: e.redo_history }
}

fn insert(e: Editor, t: String, saved: List[(String, Int)]) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur), "") + t + join(drop(cs, e.cur), "")
  return Editor { text: text, cur: e.cur + str_len(t), history: saved, redo_history: [] }
}

fn delete(e: Editor, k: Int, saved: List[(String, Int)]) -> Editor {
  let cs = split(e.text, "")
  let text = join(take(cs, e.cur - k), "") + join(drop(cs, e.cur), "")
  return Editor { text: text, cur: e.cur - k, history: saved, redo_history: [] }
}

fn undo(e: Editor) -> Editor {
  return match last(e.history) {
    Some(p) => undo_to(e, p),
    None => e,
  }
}

fn undo_to(e: Editor, p: (String, Int)) -> Editor {
  let history = take(e.history, len(e.history) - 1)
  let redo_history = append(e.redo_history, (e.text, e.cur))
  return Editor { text: p.0, cur: p.1, history: history, redo_history: redo_history }
}

fn redo(e: Editor) -> Editor {
  return match last(e.redo_history) {
    Some(p) => redo_to(e, p),
    None => e,
  }
}

fn redo_to(e: Editor, p: (String, Int)) -> Editor {
  let history = append(e.history, (e.text, e.cur))
  let redo_history = take(e.redo_history, len(e.redo_history) - 1)
  return Editor { text: p.0, cur: p.1, history: history, redo_history: redo_history }
}

fn text_editor(ops: List[EditOp]) -> String {
  let start = Editor { text: "", cur: 0, history: [], redo_history: [] }
  return fold(ops, start, |e, op| step(e, op)).text
}

