import re  # noqa: E402

_VERSION_FULLMATCH: Callable[[str], re.Match[str] | None] = re.compile(
    r"[0-9]+(?:\.[0-9]+){0,3}"
).fullmatch


def _parse(version: str) -> list[int] | None:
    if version.startswith(("v", "V")):
        version = version[1:]
    if _VERSION_FULLMATCH(version) is None:
        return None
    return [int(part) for part in version.split(".")]


