export function caesar_shift(s: string, k: number): string {
  let out = "";
  for (const c of s) {
    const code = c.charCodeAt(0);
    let base: number;
    if (code >= 97 && code <= 122) {
      base = 97;
    } else if (code >= 65 && code <= 90) {
      base = 65;
    } else {
      out += c;
      continue;
    }
    const i = (((code - base + k) % 26) + 26) % 26;
    out += String.fromCharCode(base + i);
  }
  return out;
}

