from typing import Callable, Generic, Literal, TypedDict, TypeVar

# ruff: noqa: F401, I001


def wrap_text(s: str, width: int) -> list[str]:
    """Greedily wrap space-separated words, splitting long words for positive widths."""
    lines: list[str] = []
    current = ""
    for word in s.split(" "):
        if not word:
            continue
        step = width if width > 0 else len(word)
        for start in range(0, len(word), step):
            piece = word[start : start + step]
            if not current:
                current = piece
            elif len(current) + 1 + len(piece) <= width:
                current = f"{current} {piece}"
            else:
                lines.append(current)
                current = piece
    if current:
        lines.append(current)
    return lines

