Instr = Push | Pop | Add | Sub | Mul | Div | Mod | Dup | Swap | Jz | Jmp | Print | Halt


STEP_LIMIT = 1000

STACK_NEEDS: dict[str, int] = {
    "Pop": 1, "Dup": 1, "Print": 1, "Jz": 1,
    "Add": 2, "Sub": 2, "Mul": 2, "Div": 2, "Mod": 2, "Swap": 2,
}

BINARY_OPS: dict[str, Callable[[int, int], int]] = {
    "Add": lambda a, b: a + b,
    "Sub": lambda a, b: a - b,
    "Mul": lambda a, b: a * b,
