export function wrap_text(s: string, width: number): string[] {
  const chunkSize = Math.floor(width);
  const words = s.split(" ").filter((w) => w !== "");
  const pieces = words.flatMap((word) => {
    if (!(chunkSize >= 1 && word.length > chunkSize)) return [word];

    const chunks: string[] = [];
    for (let start = 0; start < word.length; start += chunkSize) {
      chunks.push(word.slice(start, start + chunkSize));
    }
    return chunks;
  });

  const lines: string[] = [];
  let cur = "";
  for (const piece of pieces) {
    if (cur === "") cur = piece;
    else if (cur.length + 1 + piece.length <= width) cur += " " + piece;
    else {
      lines.push(cur);
      cur = piece;
    }
  }
  if (cur !== "") lines.push(cur);
  return lines;
}

