type Sale = { region: string; product: string; units: number; price_cents: number };

function compareCodePoints(a: string, b: string): number {
  let offset = 0;
  for (const char of a) {
    const right = b.codePointAt(offset);
    if (right === undefined) return 1;
    const left = char.codePointAt(0)!;
    if (left !== right) return left - right;
    offset += char.length;
  }
  return offset === b.length ? 0 : -1;
}

export function top_product_per_region(sales: Sale[]): ([string, string, number])[] {
  const byRegion = new Map<string, Map<string, number>>();
  for (const s of sales) {
    let products = byRegion.get(s.region);
    if (!products) {
      products = new Map();
      byRegion.set(s.region, products);
    }
    products.set(s.product, (products.get(s.product) ?? 0) + s.units * s.price_cents);
  }

  const regions = [...byRegion.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  const result: [string, string, number][] = [];

  for (const [region, products] of regions) {
    let bestRevenue: number | undefined;
    let winners: string[] = [];
    for (const [product, revenue] of products) {
      if (bestRevenue === undefined || revenue > bestRevenue) {
        bestRevenue = revenue;
        winners = [product];
      } else if (revenue === bestRevenue) {
        winners.push(product);
      }
    }

    if (bestRevenue !== undefined) {
      winners.sort(compareCodePoints);
      for (const product of winners) {
        result.push([region, product, bestRevenue]);
      }
    }
  }

  return result;
}

